using ISMTelemetry;
using Microsoft.Dynamics.Integration.Telemetry.AppInsights;

/// <summary>
/// Starts the process-local telemetry collector during AOS startup.
/// </summary>
internal final class ISMTelemetryCollectorStartup
{
}

Method.Source:
/// <summary>
/// Starts the collector once for the current AOS application domain.
/// </summary>
[SubscribesTo(
    classStr(ApplicationStartupEventManager),
    staticdelegateStr(ApplicationStartupEventManager, onSystemStartup))]
public static void onSystemStartup()
{
    ISMTelemetryCollectorStartup::ensureStarted();
}

/// <summary>
/// Starts the collector when the session startup event path does not invoke onSystemStartup.
/// </summary>
/// <param name="_isBatch">Whether the session is a batch session.</param>
/// <param name="_isInteractive">Whether the session is interactive.</param>
[SubscribesTo(
    classStr(ApplicationStartupEventManager),
    staticdelegateStr(ApplicationStartupEventManager, onSessionCreated)),
SuppressBPWarning(
    'BPParameterNotUsed',
    'The parameters are required by the subscribed delegate.')]
public static void onSessionCreated(
    boolean _isBatch,
    boolean _isInteractive)
{
    ISMTelemetryCollectorStartup::ensureStarted();
}

/// <summary>
/// Starts the process-local collector if custom metrics are enabled.
/// </summary>
private static void ensureStarted()
{
    try
    {
        if (SysIntParameters::Find().CaptureCustomMetrics)
        {
            TelemetryClient telemetryClient =
                SysApplicationInsightsTelemetryClientFactory::constructDefaultClient();

            if (telemetryClient)
            {
                TelemetryCollectorHost::EnsureStarted(telemetryClient);
            }
        }
    }
    catch
    {
        System.Exception exception = CLRInterop::getLastException();
        warning(strFmt(
            "ISM telemetry collector could not start: %1",
            exception.ToString()));
    }
}
